115	/** What a server advertised that it should not have, and what it did not advertise. */
116	export interface ToolSetMismatch {
117	  readonly server: string;
118	  /** Advertised and not expected — the direction a guard failing open takes. */
119	  readonly unexpected: readonly string[];
120	  /** Expected and not advertised — a server that has lost a tool, or has not started. */
121	  readonly missing: readonly string[];
122	}
123	
124	/**
125	 * The tools a server contributed, with the core's own removed.
126	 *
127	 * Takes what the agent was handed for a definition naming ONE server, which is why it
128	 * can be a filter rather than an attribution: with one server in the definition every
129	 * remaining name is that server's. Keying on `server__` instead would read an
130	 * `unprefixed` server's six tools as zero — the shape `probes/tool-servers.ts` was
131	 * caught by once already.
132	 */
133	export function serverContributed(advertised: readonly string[]): string[] {
134	  return advertised.filter((name) => !name.startsWith(CORE_TOOL_PREFIX));
135	}
136	
137	/**
138	 * Hold one server's advertised tools to its set, exactly.
139	 *
140	 * Both directions, and the less obvious one earns its place: a `missing` tool is how
141	 * a server that came up empty, or one whose allowlist has gone from narrowing to
142	 * forbidding, becomes a failure rather than a pass over an empty list. An expectation
143	 * that only refused extras would be satisfied by a server offering nothing.
144	 */
145	export function compareToolSet(expected: ExactToolSet, advertised: readonly string[]): ToolSetMismatch | undefined {
146	  const seen = new Set(serverContributed(advertised));
147	  const allowed = new Set(expected.tools);
148	  const unexpected = [...seen].filter((name) => !allowed.has(name)).sort();
149	  const missing = expected.tools.filter((name) => !seen.has(name));
150	  if (unexpected.length === 0 && missing.length === 0) return undefined;
151	  return { server: expected.server, unexpected, missing };
152	}
153	
154	/** One line a person can act on, naming what changed and what it costs. */
155	export function describeMismatch(expected: ExactToolSet, mismatch: ToolSetMismatch): string {
156	  const parts: string[] = [];
157	  if (mismatch.unexpected.length > 0) {
158	    parts.push(`advertises ${mismatch.unexpected.join(", ")}, which it must not`);
159	  }
160	  if (mismatch.missing.length > 0) {
161	    parts.push(`does not advertise ${mismatch.missing.join(", ")}, which it must`);
162	  }
163	  return (
164	    `${expected.server} ${parts.join("; and ")}. Expected exactly {${expected.tools.join(", ")}}. ` +
165	    expected.promise
166	  );
167	}

